import { deepEqualJson } from "./deepEqual";
import type { BaselineRow, EditLog, RowEdit, RowId } from "./types";

/**
 * Builds the reducer's `baseline` map (and `projectRows`' equivalent
 * input) from the hook's `BaselineRow<TRow>[]`. `undefined` in,
 * `undefined` out — never coerced to an empty `Map`, which would be
 * misread as "this rowId is provably not on the server"
 * (`resolveOpAgainstBaseline`) instead of "not yet known".
 *
 * Pure: never mutates `baseline`.
 */
export function toBaselineMap<TRow extends object>(
  baseline: readonly BaselineRow<TRow>[] | undefined,
): ReadonlyMap<RowId, TRow> | undefined {
  if (baseline === undefined) return undefined;
  return new Map(baseline.map((entry) => [entry.rowId, entry.row] as const));
}

/** Options for {@link applyEditToLog}. */
export interface ApplyEditOptions<TRow extends object> {
  /**
   * rowId → the unedited server row. Used to canonicalize an `update`
   * patch back to "no edit at all" once it matches what the server
   * already has — that is what makes "dirty" derived rather than sticky
   * (mild → moderate → mild leaves the section pristine).
   *
   * A rowId absent from this map (or the map itself absent) can never be
   * detected as "reverted" — by design. A row with no baseline entry is
   * an add, and an add was never on the server to revert to.
   */
  baseline?: ReadonlyMap<RowId, TRow>;
  /**
   * An ADDED row that satisfies this after an `update` replaces its patch
   * is annihilated — the row never reached the server, so clearing it
   * back to nothing is indistinguishable from never adding it. Applies
   * only to the existing-`add` × incoming-`update` cell, never to a
   * re-`add`, which is a fresh, deliberate creation.
   */
  isEmptyRow?: (row: TRow) => boolean;
}

/**
 * Folds one more edit into the log, preserving the invariant the whole
 * state core depends on: **at most one entry per rowId, always**. This is
 * what makes "a clinician who never touched a section sends zero requests
 * for it" true by construction rather than by convention.
 *
 * Pure and total — never mutates `log` or an existing entry. The
 * assistant's edit path calls this same function, so human and assistant
 * input cannot diverge.
 *
 * Coalescing table (existing entry's op × incoming edit's op):
 *
 * | existing  | incoming `add`         | incoming `update`         | incoming `remove` |
 * |-----------|-------------------------|----------------------------|--------------------|
 * | *(none)*  | append `add`            | append `update`; drop if patch canonicalizes to baseline | append `remove` |
 * | `add`     | replace patch, stays `add` | replace patch, stays `add`; **annihilate instead if `isEmptyRow(patch)`** | **annihilate** (row never reached the server) |
 * | `update`  | **resolved against `baseline`** — `add` if the rowId provably isn't in it, else replace patch and stay `update` | replace patch, canonicalize against baseline, **drop if reverted** | replace with `remove` |
 * | `remove`  | **resolved against `baseline`** — `add` if the rowId provably isn't in it, else `update` (restore-and-patch) | same resolution as the `add` column | keep `remove` (idempotent) |
 *
 * The "resolved against `baseline`" cells never trust an op label as a
 * proxy for "this rowId is really on the server" — both labels are
 * forgeable by annihilation (see `resolveOpAgainstBaseline`); the
 * baseline map is the only source of truth consulted there.
 */
export function applyEditToLog<TRow extends object>(
  log: EditLog<TRow>,
  edit: RowEdit<TRow>,
  options: ApplyEditOptions<TRow> = {},
): EditLog<TRow> {
  const { baseline, isEmptyRow } = options;
  const index = log.findIndex((entry) => entry.rowId === edit.rowId);

  if (index === -1) {
    return appendFresh(log, edit, baseline);
  }

  const existing = log[index];
  const resolved = coalesce(existing, edit, baseline, isEmptyRow);

  if (resolved === null) {
    // Annihilated (add→remove) — drop the slot, preserving the relative
    // order of every other entry.
    return [...log.slice(0, index), ...log.slice(index + 1)];
  }

  const next = log.slice();
  next[index] = resolved;
  return next;
}

function appendFresh<TRow extends object>(
  log: EditLog<TRow>,
  edit: RowEdit<TRow>,
  baseline: ReadonlyMap<RowId, TRow> | undefined,
): EditLog<TRow> {
  if (edit.op === "update" && isRevertedToBaseline(edit, baseline)) {
    // A no-op update against a known baseline is never recorded in the
    // first place — the section stays honestly pristine.
    return log.slice();
  }
  // Appends go to the end — add order is display order for added rows,
  // and this is the only path that grows the log's length.
  return [...log, edit];
}

function coalesce<TRow extends object>(
  existing: RowEdit<TRow>,
  incoming: RowEdit<TRow>,
  baseline: ReadonlyMap<RowId, TRow> | undefined,
  isEmptyRow: ((row: TRow) => boolean) | undefined,
): RowEdit<TRow> | null {
  switch (existing.op) {
    case "add":
      return coalesceOntoAdd(existing, incoming, isEmptyRow);
    case "update":
      return coalesceOntoUpdate(existing, incoming, baseline);
    case "remove":
      return coalesceOntoRemove(existing, incoming, baseline);
  }
}

function coalesceOntoAdd<TRow extends object>(
  existing: RowEdit<TRow>,
  incoming: RowEdit<TRow>,
  isEmptyRow: ((row: TRow) => boolean) | undefined,
): RowEdit<TRow> | null {
  if (incoming.op === "remove") {
    // The row never reached the server — there is nothing to tell it
    // about. Annihilate; the log returns to pristine for this rowId.
    return null;
  }
  // incoming is "add" (a re-add) or "update" — either way the row still
  // hasn't been created server-side, so it stays an `add`; `patch` is the
  // complete row, so this is a full replace.
  //
  // isEmptyRow applies only to the `update` case: an update that empties
  // an added row is the "clear it back out" gesture, and the row never
  // reached the server, so annihilating it is indistinguishable from
  // never adding it. A re-`add` is a deliberate creation and is never
  // annihilated by content.
  if (incoming.op === "update" && isEmptyRow?.(incoming.patch)) {
    return null;
  }
  return { rowId: existing.rowId, op: "add", patch: incoming.patch };
}

function coalesceOntoUpdate<TRow extends object>(
  existing: RowEdit<TRow>,
  incoming: RowEdit<TRow>,
  baseline: ReadonlyMap<RowId, TRow> | undefined,
): RowEdit<TRow> | null {
  if (incoming.op === "remove") {
    return { rowId: existing.rowId, op: "remove", patch: incoming.patch };
  }
  if (incoming.op === "add") {
    // An existing `update` entry does not prove a real baseline row — the
    // label is forgeable by annihilation (see resolveOpAgainstBaseline) —
    // so resolve against the baseline map: keeping `add` here for a row
    // the server already has would instruct it to CREATE a duplicate
    // clinical record.
    const op = resolveOpAgainstBaseline(existing.rowId, baseline);
    return { rowId: existing.rowId, op, patch: incoming.patch };
  }
  // incoming is "update": replace the patch (always the complete row),
  // then canonicalize against baseline — the "edit-then-revert" case:
  // mild → moderate → mild must leave the section clean.
  if (
    isRevertedToBaseline(
      { rowId: existing.rowId, patch: incoming.patch },
      baseline,
    )
  ) {
    return null;
  }
  return { rowId: existing.rowId, op: "update", patch: incoming.patch };
}

function coalesceOntoRemove<TRow extends object>(
  existing: RowEdit<TRow>,
  incoming: RowEdit<TRow>,
  baseline: ReadonlyMap<RowId, TRow> | undefined,
): RowEdit<TRow> | null {
  if (incoming.op === "remove") {
    return existing;
  }
  // incoming is "add" or "update": a resurrection of a row carrying a
  // pending `remove`. The existing `remove` does not prove the rowId is a
  // server row — `add(u) → remove(u)` annihilates the pair (erasing u's
  // history from the log), and a second `remove(u)` then reaches
  // `appendFresh`, which appends unconditionally — so the outcome is
  // resolved against the baseline map: `add` if the rowId provably isn't
  // a server row, `update` (restore-and-patch) otherwise. Both incoming
  // ops resolve identically, by data.
  //
  // Deliberate asymmetry with coalesceOntoUpdate: a restore whose patch
  // deep-equals the baseline row still records an `update` instead of
  // dropping it — remove-then-restore-unchanged is not treated as
  // "never happened".
  const op = resolveOpAgainstBaseline(existing.rowId, baseline);
  return { rowId: existing.rowId, op, patch: incoming.patch };
}

/**
 * Decides what a resurrection/re-add op should BECOME, based on whether
 * the rowId is a row the server has — never on the op label the existing
 * entry or the incoming edit carries: annihilation erases a rowId's
 * history from the log, so both labels are forgeable (see the call sites
 * in `coalesceOntoRemove` and `coalesceOntoUpdate`). The baseline map is
 * the only source of truth consulted here.
 *
 * When `baseline` is not supplied there is genuinely no way to know, and
 * `"update"` is the documented, conservative fallback: a wrong `update`
 * surfaces as a loud 404/400, while a wrong `add` would silently create
 * a duplicate clinical row — data corruption, the worse failure. Every
 * real caller (via `useStructuredRows`) supplies the full map.
 */
function resolveOpAgainstBaseline<TRow extends object>(
  rowId: RowId,
  baseline: ReadonlyMap<RowId, TRow> | undefined,
): "add" | "update" {
  if (baseline === undefined) return "update";
  return baseline.has(rowId) ? "update" : "add";
}

/**
 * Has this edit's patch collapsed back to exactly what the baseline
 * already holds for this rowId? Structural (JSON) equality, per
 * `deepEqualJson`'s doc comment — not `===`, since a patch is routinely
 * rebuilt as a fresh object (`{ ...baselineRow, field: value }`).
 *
 * Deliberately `false` when there is no baseline entry for this rowId
 * (map absent, or rowId not present in it): nothing to compare against
 * means nothing can be called a revert.
 */
function isRevertedToBaseline<TRow extends object>(
  edit: { rowId: RowId; patch: TRow },
  baseline: ReadonlyMap<RowId, TRow> | undefined,
): boolean {
  const baselineRow = baseline?.get(edit.rowId);
  if (baselineRow === undefined) return false;
  return deepEqualJson(edit.patch, baselineRow);
}

/**
 * Collapses a log to at most one edit per rowId: content follows the LAST
 * entry for a rowId, position its FIRST appearance. Identity for any log
 * `applyEditToLog` produced (one entry per rowId already), but a restored
 * draft's per-record validation admits duplicate rowIds the reducer never
 * emits — every consumer (`resolveChanges`, `findOrphanRowIds`) iterates
 * this so one identity is acted on exactly once.
 *
 * Pure: never mutates `log`; returns a fresh array.
 */
export function dedupeEditsFirstAppearance<TRow extends object>(
  log: EditLog<TRow>,
): readonly RowEdit<TRow>[] {
  // A Map keyed by rowId gives exactly these semantics: re-setting an
  // existing key keeps its original position and replaces its value.
  const editByRowId = new Map<RowId, RowEdit<TRow>>();
  for (const edit of log) editByRowId.set(edit.rowId, edit);
  return [...editByRowId.values()];
}

import { dedupeEditsFirstAppearance } from "./editLog";
import type {
  BaselineRow,
  EditLog,
  ProjectedRow,
  RowEdit,
  RowId,
  SoftDeleteDescriptor,
} from "./types";

/**
 * Options for {@link projectRows}. Two deliberate narrowings:
 *
 *  - No `single` flag: a singleton's at-most-one-row invariant is a rowId
 *    stability property (`SINGLETON_ROW_ID`), not a truncation this
 *    function performs — see {@link truncateToSingletonRow}.
 *  - No orphan channel bundled into the return: {@link findOrphanRowIds}
 *    is the sibling function over the same `(baseline, log)` inputs.
 *
 * `baseline` is the COMPLETE fetched server-row set, or `undefined` while
 * unknown — never a partial array standing in for "loading".
 */
export interface ProjectRowsOptions<TRow extends object> {
  /**
   * How a type marks — instead of deletes — a baseline row's removal.
   * See `SoftDeleteDescriptor` in `./types` for the full contract.
   *
   * Read here only via `isDeleted`, to decide `ProjectedRow.softDeleted`
   * for whatever row content is already on screen — a row can be flagged
   * because its baseline data already carries the marker (soft-deleted in
   * an earlier session) just as much as because this session's edit added
   * it. `projectRows` never writes the marker itself; that is
   * `removeRow`'s job.
   */
  softDelete?: SoftDeleteDescriptor<TRow>;
  /**
   * DISPLAY ONLY. Applied as a stable sort over the canonical order
   * (baseline order, then added rows in edit-log order). Nothing
   * downstream reads row order — requests are built from the edit log,
   * identity from `rowId` — so this sort can never reach the edit log, a
   * request body, or a rowId.
   */
  displayOrder?: (a: TRow, b: TRow) => number;
}

/**
 * Computes what the clinician SEES for one structured section: baseline
 * (complete fetched server-row set, or `undefined` while unknown) plus
 * the pending edit log. This is what `values[0].value` carries for every
 * v2 structured question — the answered predicate, outline ticks,
 * readonly renderers and server-draft dumps all read the array this
 * returns. Pure: never mutates `baseline` or `log`.
 *
 * Steps, in order:
 *
 * 1. Baseline rows, in the order the query layer returned them — a row's
 *    position never depends on whether it was edited. An `op: "remove"`
 *    edit hides the row outright (a marking type's `removeRow` records an
 *    `update`, never a `remove`, so this branch is a genuine delete). Any
 *    other matching edit contributes `edit.patch` as the row's content —
 *    a full REPLACE, never a merge: `patch` is always the complete row.
 *
 * 2. Added rows, in edit-log order — stable across a baseline refetch. An
 *    `add` whose rowId step 1 already emitted is SKIPPED: a restored
 *    draft can carry an `add` recorded before the server row existed
 *    while the fresh baseline now has that id — the baseline row wins,
 *    with the add's patch as its content, rather than one rowId rendering
 *    as two rows.
 *
 * 3. When `baseline` is a known array, every remaining `update`/`remove`
 *    is an orphan — intent about a row the complete baseline lacks — and
 *    is never rendered; {@link findOrphanRowIds} names these. When
 *    `baseline` is `undefined` (loading/errored), an unmatched `update`
 *    is unresolved, not orphaned — see step 3 in the implementation.
 *
 * 4. `displayOrder`, applied last via a stable sort.
 */
export function projectRows<TRow extends object>(
  baseline: readonly BaselineRow<TRow>[] | undefined,
  log: EditLog<TRow>,
  options: ProjectRowsOptions<TRow> = {},
): ProjectedRow<TRow>[] {
  const { softDelete, displayOrder } = options;

  const editByRowId = new Map<RowId, RowEdit<TRow>>();
  for (const edit of log) editByRowId.set(edit.rowId, edit);

  // `undefined` means "not yet known"; only the ORIGINAL `baseline`
  // parameter is what step 3 branches on.
  const baselineRows = baseline ?? [];
  const baselineRowIds = new Set<RowId>(
    baselineRows.map((entry) => entry.rowId),
  );

  const rows: ProjectedRow<TRow>[] = [];

  // 1. Baseline, in the order the query layer returned it.
  for (const entry of baselineRows) {
    const edit = editByRowId.get(entry.rowId);
    if (edit?.op === "remove") continue;

    const row = edit ? edit.patch : entry.row;

    rows.push({
      rowId: entry.rowId,
      row,
      origin: "baseline",
      edited: edit !== undefined,
      softDeleted: softDelete?.isDeleted(row) ?? false,
    });
  }

  // 2. Adds, in edit-log order. Two guards:
  //    - `editByRowId.get(edit.rowId) !== edit` skips an entry a later
  //      entry for the same rowId superseded (`applyEditToLog` never
  //      produces duplicates, but a restored draft's per-record
  //      validation admits them).
  //    - `baselineRowIds.has(edit.rowId)` skips a rowId loop 1 already
  //      emitted — see the collision note in the doc comment.
  for (const edit of log) {
    if (editByRowId.get(edit.rowId) !== edit) continue;
    if (edit.op !== "add") continue;
    if (baselineRowIds.has(edit.rowId)) continue;

    rows.push({
      rowId: edit.rowId,
      row: edit.patch,
      origin: "added",
      edited: true,
      softDeleted: softDelete?.isDeleted(edit.patch) ?? false,
    });
  }

  // 3. `baseline === undefined` means the query is loading or errored,
  //    NOT "the server confirmed zero rows" — an unmatched `update` is
  //    unresolved, not a confirmed orphan. Render it from its own patch
  //    (already the complete row) so a restored draft stays visible — and
  //    still submittable — during the loading window. `origin` is
  //    "baseline" so the row doesn't visually flip when the real baseline
  //    arrives and confirms it.
  if (baseline === undefined) {
    for (const edit of log) {
      if (editByRowId.get(edit.rowId) !== edit) continue;
      if (edit.op !== "update") continue;

      rows.push({
        rowId: edit.rowId,
        row: edit.patch,
        origin: "baseline",
        edited: true,
        softDeleted: softDelete?.isDeleted(edit.patch) ?? false,
      });
    }
  }

  // 4. Display sort — output only.
  if (displayOrder) {
    rows.sort((a, b) => displayOrder(a.row, b.row));
  }

  return rows;
}

/**
 * Names the rowIds {@link projectRows} silently drops: a restored edit
 * whose baseline row vanished server-side must be LISTED to the
 * clinician, not just disappear. Computed over the identical
 * `(baseline, log)` inputs `projectRows` takes, so the two can never
 * disagree about which edits are showing versus orphaned.
 *
 * `undefined` baseline returns `[]`: unresolved is not confirmed-gone.
 *
 * The predicate is `op !== "add" && !baselineRowIds.has(rowId)` —
 * deliberately NOT "not rendered", which would also flag the clinician's
 * own remove of an added row and every ordinary `add`.
 *
 * Pure; duplicates in a malformed log are reported once
 * ({@link dedupeEditsFirstAppearance}).
 */
export function findOrphanRowIds<TRow extends object>(
  baseline: readonly BaselineRow<TRow>[] | undefined,
  log: EditLog<TRow>,
): readonly RowId[] {
  if (baseline === undefined) return [];
  const baselineRowIds = new Set<RowId>(baseline.map((entry) => entry.rowId));

  const orphanRowIds: RowId[] = [];
  for (const edit of dedupeEditsFirstAppearance(log)) {
    if (edit.op !== "add" && !baselineRowIds.has(edit.rowId)) {
      orphanRowIds.push(edit.rowId);
    }
  }
  return orphanRowIds;
}

/**
 * Drops every {@link findOrphanRowIds} entry from `log`: what remains is
 * exactly what `projectRows` still renders (plus what it presumes during
 * the loading window) — never intent about a row the complete, known
 * baseline has confirmed gone.
 *
 * This lives at the hook, not the compose/submit seam: `toRequests` and
 * `resolveChanges` never hold a baseline at submit time, so
 * `useStructuredRows` — the one place `baseline` and `edits` coexist —
 * must prune before its `commit` write.
 *
 * Deliberately NOT the clinician's `removeRow` path: no soft-delete
 * marker is written and no request is implied — the entry is simply
 * excised. A no-op while `baseline` is `undefined`.
 *
 * Pure; returns the SAME `log` reference when nothing is dropped, so a
 * caller can skip a write on reference equality.
 */
export function pruneOrphanEdits<TRow extends object>(
  baseline: readonly BaselineRow<TRow>[] | undefined,
  log: EditLog<TRow>,
): EditLog<TRow> {
  const orphanRowIds = findOrphanRowIds(baseline, log);
  if (orphanRowIds.length === 0) return log;
  const orphanSet = new Set(orphanRowIds);
  return log.filter((edit) => !orphanSet.has(edit.rowId));
}

/**
 * Restricts an edit log to at most the ONE rowId {@link projectRows}
 * would show as `rows[0]` for the same `(baseline, log)` pair.
 *
 * Why: singleton mode only ever SHOWS `rows[0]`, but nothing upstream
 * stops the log from holding a second rowId — an `initialEdits` seed
 * writes an `add` under `singletonRowId`, an `add` is never an orphan,
 * and if a real baseline row for the same question resolves under its
 * OWN server id while that seed is still in the log, the two coexist: a
 * caller writing `edits` from every projected row would silently submit
 * BOTH on Save. Keeps whichever rowId `projectRows` shows FIRST, so "the
 * one row" is defined by the exact projection the clinician sees.
 *
 * Unreachable for every type shipped so far — closed by construction
 * rather than left as a trap for the next singleton.
 *
 * Pure; returns the SAME `log` reference when there is nothing to drop.
 */
export function truncateToSingletonRow<TRow extends object>(
  baseline: readonly BaselineRow<TRow>[] | undefined,
  log: EditLog<TRow>,
  options: ProjectRowsOptions<TRow> = {},
): EditLog<TRow> {
  if (log.length === 0) return log;
  // Checks the FULL PROJECTION's row count, not `log.length` — a baseline
  // can contribute rows the log never mentions (a real baseline row under
  // its own id, plus a single seeded `add` under a different id, is a
  // one-entry log that still projects TWO rows).
  const rows = projectRows(baseline, log, options);
  if (rows.length <= 1) return log;
  const keepRowId = rows[0]?.rowId;
  // No row projects at all — nothing to keep; leave `log` for orphan
  // pruning to handle. Defensive: unreachable alongside `rows.length > 1`.
  if (keepRowId === undefined) return log;
  const truncated = log.filter((edit) => edit.rowId === keepRowId);
  return truncated.length === log.length ? log : truncated;
}

import { format } from "date-fns";
import { z } from "zod";

import type {
  BaselineRow,
  ProjectValues,
  SoftDeleteDescriptor,
} from "@/components/QuestionnaireV2/structured/core/types";
import { listProjectValues } from "@/components/QuestionnaireV2/structured/shared/listProjectValues";
import {
  onsetSchema,
  userDisplaySchema,
} from "@/components/QuestionnaireV2/structured/shared/rowSchemaPrimitives";
import { makeUpsertToRequests } from "@/components/QuestionnaireV2/structured/shared/upsertToRequests";
import { CodeSchema, type Code } from "@/types/base/code/code";
import type { Symptom, SymptomRequest } from "@/types/emr/symptom/symptom";
import {
  SYMPTOM_CLINICAL_STATUS,
  SYMPTOM_SEVERITY,
  SYMPTOM_VERIFICATION_STATUS,
} from "@/types/emr/symptom/symptom";

/** The wire request shape doubles as the editable row shape. */
export type SymptomRow = SymptomRequest;

/**
 * Assistant write guard. `category` stays a bare non-empty string — no
 * exhaustive runtime enum exists for it. Timestamp fields are read-only
 * pass-through, left as plain optional strings.
 */
export const rowSchema = z
  .object({
    id: z.string().optional(),
    clinical_status: z.enum(SYMPTOM_CLINICAL_STATUS),
    verification_status: z.enum(SYMPTOM_VERIFICATION_STATUS),
    code: CodeSchema,
    severity: z.enum(SYMPTOM_SEVERITY),
    onset: onsetSchema.optional(),
    recorded_date: z.string().optional(),
    note: z.string().optional(),
    encounter: z.string().min(1),
    category: z.string().min(1),
    created_date: z.string().optional(),
    updated_date: z.string().optional(),
    created_by: userDisplaySchema.optional(),
  })
  .strict();

/**
 * Removing a row that exists on the server flips `verification_status` to
 * `entered_in_error` and keeps it visible; a row that never reached the
 * server is dropped outright. `useStructuredRows` dispatches on this
 * descriptor by row origin.
 */
export const SYMPTOM_SOFT_DELETE: SoftDeleteDescriptor<SymptomRow> = {
  patch: { verification_status: "entered_in_error" },
  isDeleted: (row) => row.verification_status === "entered_in_error",
};

/**
 * The calendar date an ISO instant was RECORDED on, taken off the string
 * rather than rendered from a `Date`: rendering resolves the instant on the
 * BROWSER's clock, so an onset stored at the server's own offset comes out a
 * day early anywhere west of it. A structured patch always ships the
 * COMPLETE row, so a clinician editing only the severity would write that
 * shifted onset back — this derivation must not depend on where the browser
 * is.
 */
function isoCalendarDate(value: string): string {
  return value.slice(0, 10);
}

/**
 * `onset_datetime` cut down to the bare date the editor's `<input
 * type="date">` speaks. An onset carrying no datetime at all (FHIR allows
 * `onset_age`/`onset_string` alone) drops the KEY rather than storing
 * `""` — `onsetSchema` rejects an empty date, so an `""` here would make
 * every such baseline row unpatchable by the assistant.
 */
function toRowOnset(onset: Symptom["onset"]): SymptomRow["onset"] {
  if (!onset) return undefined;
  const { onset_datetime, ...rest } = onset;
  if (!onset_datetime) return rest;
  return { ...rest, onset_datetime: isoCalendarDate(onset_datetime) };
}

/**
 * Read shape → the row this question edits. Uses `date-fns` directly —
 * `@/Utils/utils` transitively reads `import.meta.env` via `@careConfig`,
 * undefined under `node --test`.
 */
export function toSymptomRow(symptom: Symptom): SymptomRow {
  return {
    id: symptom.id,
    code: symptom.code,
    clinical_status: symptom.clinical_status,
    verification_status: symptom.verification_status,
    severity: symptom.severity,
    onset: toRowOnset(symptom.onset),
    recorded_date: symptom.recorded_date,
    note: symptom.note,
    category: symptom.category,
    encounter: symptom.encounter,
    created_date: symptom.created_date,
    updated_date: symptom.updated_date,
    created_by: symptom.created_by,
  };
}

/**
 * Keyed by the server id so `removeRow` distinguishes baseline
 * (soft-delete) from added (annihilate) rows. Callers pass `undefined`,
 * never `[]`, while the fetch is unresolved.
 */
export function toBaselineRows(
  symptoms: readonly Symptom[],
): BaselineRow<SymptomRow>[] {
  return symptoms.map((symptom) => ({
    rowId: symptom.id,
    row: toSymptomRow(symptom),
  }));
}

/** Every symptom this question records is a `problem_list_item`; no
 *  control exposes the field. */
const SYMPTOM_CATEGORY = "problem_list_item";

/**
 * New rows default to active/confirmed, severity "moderate", and onset today.
 * `encounter` is set at creation because a row's `patch` must be the complete
 * row.
 */
export function newSymptomRow(code: Code, encounterId: string): SymptomRow {
  return {
    code,
    clinical_status: "active",
    verification_status: "confirmed",
    severity: "moderate",
    category: SYMPTOM_CATEGORY,
    onset: { onset_datetime: format(new Date(), "yyyy-MM-dd") },
    encounter: encounterId,
  };
}

/** Duplicate-guard key for `findDuplicateCandidates`, which already
 *  excludes soft-deleted (entered_in_error) rows from its seen set. An
 *  empty code yields `undefined`, excluding the row from matching. */
export function symptomDuplicateKey(row: SymptomRow): string | undefined {
  return row.code.code || undefined;
}

export const projectValues: ProjectValues<SymptomRow> =
  listProjectValues("symptom");

/**
 * Reuses a historical symptom as a NEW row for this encounter: the server
 * id is stripped — keeping it would make the upsert update the original
 * record in place — and `encounter` is re-stamped to the current
 * encounter. Every other field carries over unchanged.
 */
export function toReusedSymptomRow(
  row: SymptomRow,
  encounterId: string,
): SymptomRow {
  const { id: _id, ...rest } = row;
  return { ...rest, encounter: encounterId };
}

/** A reused historical symptom can carry another encounter — see
 *  `makeUpsertToRequests` for the re-stamping contract every upsert type
 *  shares. */
export const toRequests = makeUpsertToRequests<SymptomRow>({
  type: "symptom",
  resource: "symptom",
  softDelete: SYMPTOM_SOFT_DELETE,
});

/**
 * Canonical list of structured question types — the single runtime source
 * the `StructuredQuestionType` union derives from. Lives in the types layer
 * so `src/types/*` never imports from the components tree.
 *
 * Adding a type here is step one of the checklist in
 * `src/components/QuestionnaireV2/structured/` — the total registry there
 * refuses to compile until the new member has a definition.
 */
export const STRUCTURED_QUESTION_TYPES = [
  "allergy_intolerance",
  "medication_request",
  "medication_statement",
  "symptom",
  "diagnosis",
  "encounter",
  "time_of_death",
  "files",
  "service_request",
  "charge_item",
  "appointment",
] as const;

export type StructuredQuestionType = (typeof STRUCTURED_QUESTION_TYPES)[number];

/**
 * A structured type contributed at runtime by a federation plugin. Always
 * namespaced `{plugin_slug}.{type_name}` — bare names stay reserved for
 * core, so a plugin can never shadow a built-in type. The template literal
 * documents the shape to the type system; the real gate is
 * `PLUGIN_STRUCTURED_TYPE_PATTERN` below (TS cannot express the character
 * class), enforced at registration and by `isPluginStructuredTypeName`.
 */
export type PluginStructuredTypeName = `${string}.${string}`;

/** The one definition of a well-formed plugin type id. Both the registry's
 *  throw-on-register check and the `isPluginStructuredTypeName` guard read
 *  it, so there is a single source for the rule. */
export const PLUGIN_STRUCTURED_TYPE_PATTERN = /^[a-z0-9_]+\.[a-z0-9_]+$/;

/**
 * What a `structured_type` field may hold: a core type or a plugin one.
 * Keeping the core union as a member means a `switch`/`===` on a core
 * literal still narrows — the template-literal member never swallows it.
 */
export type StructuredTypeValue =
  StructuredQuestionType | PluginStructuredTypeName;

/** Narrows a `structured_type` back to a core member — the guard anything
 *  keyed on the closed core union (a total `Record`, a core-only handler
 *  map) needs now that the field also admits plugin ids. */
export function isCoreStructuredType(
  value: string,
): value is StructuredQuestionType {
  return (STRUCTURED_QUESTION_TYPES as readonly string[]).includes(value);
}

/** Narrows a registered plugin type's id to `PluginStructuredTypeName` —
 *  what a consumer holding the definition's `string` `type` needs to put it
 *  where a `StructuredTypeValue` is expected, without a cast. */
export function isPluginStructuredTypeName(
  value: string,
): value is PluginStructuredTypeName {
  return PLUGIN_STRUCTURED_TYPE_PATTERN.test(value);
}

/**
 * Clinician changes to a structured section, distinct from projection display
 * state. `rowId` is stable and client-owned: the server id for existing rows,
 * or a uuid for new rows. `patch` is the complete row for every operation so
 * request composition remains self-sufficient.
 */
export type StructuredEditOp = "add" | "update" | "remove";

export interface StructuredEdit<TRow> {
  /** Server id for a row that exists on the server; uuid for an add. */
  rowId: string;
  op: StructuredEditOp;
  patch: TRow;
}

/**
 * The type-erased edit, as it is stored on a `QuestionnaireResponse`, in a
 * local draft and in a server draft's `response_dump`. A row shape is
 * opaque outside its own type module — the same honesty `unknown[]` buys
 * `ResolvedStructuredType`'s data reads — so `patch` widens to `unknown`
 * and the ONE sanctioned narrowing back happens at the registry boundary,
 * where key-correlation already guarantees the pairing.
 */
export type StructuredEditRecord = StructuredEdit<unknown>;

const STRUCTURED_EDIT_OPS: readonly string[] = ["add", "update", "remove"];

/** Is this parsed-JSON value a well-formed edit? Drafts and server dumps are
 *  untrusted blobs, and this guard is the ONLY gate one passes before
 *  `useStructuredRows` casts the sanitized log to `EditLog<TRow>`.
 *
 *  `patch` is checked for PRESENCE only — a non-null object — because it is
 *  the complete row for every op (see {@link StructuredEdit}) and the first
 *  thing every reader dereferences (`softDelete.isDeleted`, `duplicateKey`,
 *  an editor's `rowTitle`); a truncated `{ rowId, op }` entry would throw
 *  out of render and take the whole fill page with it. Its CONTENTS stay
 *  unjudged here — only the type's own row schema can rule on those, and
 *  request building has its own containment boundary. */
export function isStructuredEditRecord(
  value: unknown,
): value is StructuredEditRecord {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as { rowId?: unknown; op?: unknown; patch?: unknown };
  return (
    typeof candidate.rowId === "string" &&
    candidate.rowId.length > 0 &&
    typeof candidate.op === "string" &&
    STRUCTURED_EDIT_OPS.includes(candidate.op) &&
    typeof candidate.patch === "object" &&
    candidate.patch !== null
  );
}

/**
 * Sanitizes an untrusted edit log: drops malformed entries and collapses
 * duplicate `rowId`s to the last entry's content while preserving the first
 * entry's position. Map insertion order keeps the surviving entry at that
 * first position when an existing key is updated.
 */
export function sanitizeStructuredEditLog(
  raw: unknown,
): StructuredEditRecord[] {
  if (!Array.isArray(raw)) return [];
  const byRowId = new Map<string, StructuredEditRecord>();
  for (const entry of raw) {
    if (!isStructuredEditRecord(entry)) continue;
    byRowId.set(entry.rowId, entry);
  }
  return [...byRowId.values()];
}

