4	import type { SymptomRequest } from "@/types/emr/symptom/symptom";
5	
6	import { resolveChanges } from "./changes";
7	import { applyEditToLog } from "./editLog";
8	import { SINGLETON_ROW_ID } from "./rowIds";
9	import {
10	  add,
11	  baselineOf,
12	  makeSymptomRow,
13	  remove,
14	  update,
15	} from "./testFixtures";
16	import type { EditLog, RowEdit, SoftDeleteDescriptor } from "./types";
17	
18	/**
19	 * A small, deliberately generic row shape for the structural cases (op
20	 * routing, ordering, purity) — contrast `testFixtures.ts`'s
21	 * `makeSymptomRow`, used where the case is shape-sensitive (the
22	 * soft-delete marker field).
23	 */
24	interface TestRow {
25	  id: string;
26	  label: string;
27	}
28	
29	function row(id: string, label: string): TestRow {
30	  return { id, label };
31	}
32	
33	describe("resolveChanges — edit log resolved into create/update/remove sets", () => {
34	  it("an empty log resolves to three empty sets — a clinician who never touched the section sends zero requests for it", () => {
35	    const result = resolveChanges<TestRow>([], {});
36	
37	    assert.deepEqual(result, { creates: [], updates: [], removes: [] });
38	  });
39	
40	  it("a non-empty baseline with an empty log ALSO resolves to three empty sets — existence of server data alone must never manufacture a request", () => {
41	    const baseline = baselineOf([
42	      ["r1", row("r1", "real")],
43	      ["r2", row("r2", "also real")],
44	    ]);
45	
46	    const result = resolveChanges<TestRow>([], { baseline });
47	
48	    assert.deepEqual(result, { creates: [], updates: [], removes: [] });
49	  });
50	
51	  it("an add lands in creates, carrying the full new row (the row IS the patch)", () => {
52	    const log: EditLog<TestRow> = [add("new-1", row("new-1", "fresh"))];
53	
54	    const result = resolveChanges(log, {});
55	
56	    assert.deepEqual(result.creates, [row("new-1", "fresh")]);
57	    assert.deepEqual(result.updates, []);
58	    assert.deepEqual(result.removes, []);
59	  });
60	
61	  it("a baseline update lands in updates, carrying the full row as it now reads", () => {
62	    const log: EditLog<TestRow> = [update("r1", row("r1", "changed"))];
63	
64	    const result = resolveChanges(log, {});
65	
66	    assert.deepEqual(result.updates, [row("r1", "changed")]);
67	    assert.deepEqual(result.creates, []);
68	    assert.deepEqual(result.removes, []);
69	  });
70	
71	  it("a remove with no softDelete descriptor lands in removes carrying the BARE rowId — nothing else is needed for a real delete-by-id", () => {
72	    const log: EditLog<TestRow> = [remove("r1", row("r1", "gone"))];
73	
74	    const result = resolveChanges(log, {});
75	
76	    assert.deepEqual(result.removes, [{ rowId: "r1" }]);
77	    // Not merely `row: undefined` — the key itself must be absent, since a
78	    // hard-delete differ has no row content to send at all.
79	    assert.equal("row" in result.removes[0], false);
80	  });
81	
82	  it("a remove with a softDelete descriptor lands in removes carrying the soft-delete BODY — the last-known row with the descriptor's marker fields merged on top", () => {
83	    const lastKnown = makeSymptomRow({
84	      id: "s1",
85	      verification_status: "confirmed",
86	    });
87	    const log: EditLog<SymptomRequest> = [remove("s1", lastKnown)];
88	    const softDelete: SoftDeleteDescriptor<SymptomRequest> = {
89	      patch: { verification_status: "entered_in_error" },
90	      isDeleted: (r) => r.verification_status === "entered_in_error",
91	    };
92	
93	    const result = resolveChanges(log, { softDelete });
94	
95	    assert.deepEqual(result.removes, [
96	      {
97	        rowId: "s1",
98	        row: { ...lastKnown, verification_status: "entered_in_error" },
99	      },
100	    ]);
101	  });
102	
103	  it("ordering within each set follows the log's order — deterministic batches", () => {
104	    const log: EditLog<TestRow> = [
105	      add("a1", row("a1", "add-1")),
106	      update("u1", row("u1", "update-1")),
107	      remove("r1", row("r1", "remove-1")),
108	      add("a2", row("a2", "add-2")),
109	      remove("r2", row("r2", "remove-2")),
110	      update("u2", row("u2", "update-2")),
111	    ];
112	
113	    const result = resolveChanges(log, {});
114	
115	    assert.deepEqual(result.creates, [row("a1", "add-1"), row("a2", "add-2")]);
116	    assert.deepEqual(result.updates, [
117	      row("u1", "update-1"),
118	      row("u2", "update-2"),
119	    ]);
120	    assert.deepEqual(
121	      result.removes.map((r) => r.rowId),
122	      ["r1", "r2"],
123	    );
124	  });
125	
126	  describe("options.baseline — orphan-drop rule (mirrors projectRows' orphan rule)", () => {
127	    it("an update targeting a rowId absent from a supplied baseline is dropped entirely — not sent, not reported", () => {
128	      const baseline = baselineOf([["other", row("other", "survives")]]);
129	      const log: EditLog<TestRow> = [
130	        update("vanished-1", row("vanished-1", "stale restored intent")),
131	      ];
132	
133	      const result = resolveChanges(log, { baseline });
134	
135	      assert.deepEqual(result.updates, []);
136	    });
137	
138	    it("a remove targeting a rowId absent from a supplied baseline is dropped entirely — no soft-delete body, no bare rowId either", () => {
139	      const baseline = baselineOf([["r1", row("r1", "real")]]);
140	      const log: EditLog<TestRow> = [
141	        remove("ghost", row("ghost", "never existed")),
142	      ];
143	      const softDelete: SoftDeleteDescriptor<TestRow> = {
144	        patch: {},
145	        isDeleted: () => false,
146	      };
147	
148	      const result = resolveChanges(log, { baseline, softDelete });
149	
150	      assert.deepEqual(result.removes, []);
151	    });
152	
153	    it("an add is NEVER treated as an orphan, even though its rowId is (correctly) absent from baseline — an add is inherently a row baseline doesn't have yet", () => {
154	      const baseline = baselineOf([["r1", row("r1", "real")]]);
155	      const log: EditLog<TestRow> = [add("new-1", row("new-1", "fresh"))];
156	
157	      const result = resolveChanges(log, { baseline });
158	
159	      assert.deepEqual(result.creates, [row("new-1", "fresh")]);
160	    });
161	
162	    it("JUDGMENT CALL / documented fallback: with NO baseline supplied at all, an update or remove for any rowId is trusted and dispatched — resolveChanges cannot check what it isn't given", () => {
163	      const log: EditLog<TestRow> = [
164	        update("mystery", row("mystery", "restored intent")),
165	      ];
166	
167	      const result = resolveChanges(log, {});
168	
169	      assert.deepEqual(result.updates, [row("mystery", "restored intent")]);
170	    });
171	  });
172	
173	  describe("a remove for a row that never touched the server must not reach the wire as a phantom soft-delete create", () => {
174	    it("the exact executed sequence: add(client-only) -> remove (annihilates) -> remove (appends fresh) still drops out of removes once a complete baseline is supplied", () => {
175	      // Annihilation erases a rowId's LOG HISTORY, not its existence: a
176	      // second `remove` for the same rowId reaches `appendFresh`, which
177	      // appends unconditionally (it never consults baseline for a
178	      // `remove`) — so a rowId that never reached the server CAN surface
179	      // in a well-formed log with `op: "remove"`.
180	      const baseline = baselineOf([["someone-else", row("someone-else", "x")]]);
181	      const clientOnlyId = "client-only-uuid";
182	
183	      const afterAdd = applyEditToLog(
184	        [],
185	        add(clientOnlyId, row(clientOnlyId, "v1")),
186	        { baseline },
187	      );
188	      const afterFirstRemove = applyEditToLog(
189	        afterAdd,
190	        remove(clientOnlyId, row(clientOnlyId, "v1")),
191	        { baseline },
192	      );
193	      assert.deepEqual(afterFirstRemove, []); // annihilated — sanity check
194	
195	      const log = applyEditToLog(
196	        afterFirstRemove,
197	        remove(clientOnlyId, row(clientOnlyId, "v2")),
198	        { baseline },
199	      );
200	      // Sanity check: the reducer really did append a fresh `remove` for a
201	      // rowId `baseline` never had — this is the false-invariant shape.
202	      assert.deepEqual(log, [remove(clientOnlyId, row(clientOnlyId, "v2"))]);
203	
204	      const softDelete: SoftDeleteDescriptor<TestRow> = {
205	        patch: { label: "entered-in-error-marker" },
206	        isDeleted: (r) => r.label === "entered-in-error-marker",
207	      };
208	
209	      const result = resolveChanges(log, { baseline, softDelete });
210	
211	      // Dropped as an orphan — NOT a soft-delete body with a client-only
212	      // patch and no server id, which would silently create a phantom
213	      // entered-in-error row against an upsert-that-may-create endpoint.
214	      assert.deepEqual(result.removes, []);
215	      assert.deepEqual(result.creates, []);
216	      assert.deepEqual(result.updates, []);
217	    });
218	  });
