      row: rows[0],
      setRow,
      clearRow,
    } as unknown as StructuredRowsController<TRow, Mode>;
  }
  return {
    ...base,
    rows,
    addRow,
    addRows,
    updateRow,
    removeRow,
    isDuplicate,
  } as unknown as StructuredRowsController<TRow, Mode>;
}

