7	import {
8	  useCallback,
9	  useEffect,
10	  useMemo,
11	  useRef,
12	  useState,
13	  type ComponentType,
14	  type ReactNode,
15	} from "react";
16	import { useTranslation } from "react-i18next";
17	
18	import { cn } from "@/lib/utils";
19	
20	import { Button } from "@/components/ui/button";
21	import {
22	  DropdownMenu,
23	  DropdownMenuContent,
24	  DropdownMenuItem,
25	  DropdownMenuSeparator,
26	  DropdownMenuTrigger,
27	} from "@/components/ui/dropdown-menu";
28	
29	import type { QuestionValidationError } from "@/types/questionnaire/batch";
30	
31	import { StructuredFieldError } from "./StructuredFieldError";
32	import { selectStructuredFieldErrors } from "./structuredFieldErrors";
33	import { resolveRowErrorState } from "./structuredListRowState";
34	import { gridTemplateColumns } from "./structuredListTracks";
35	import type { ProjectedRow, RowId } from "./types";
36	
37	/**
38	 * The naming bundle every control inside a cell must carry, spread as a
39	 * single unit (`{...ctx.controlProps}`) rather than four hand-copied
40	 * attributes.
41	 *
42	 * TypeScript alone cannot make an omission loud: excess-property checking
43	 * does not flag a hyphenated attribute — named or spread — on a component
44	 * that doesn't declare it; the value compiles cleanly and is silently
45	 * dropped at runtime. The loud half is `auditCellAccessibleName` below.
46	 * This bundle just makes it ONE thing to remember per control instead of
47	 * four independently wireable attributes.
48	 */
49	export interface StructuredControlProps {
50	  id: string;
51	  "aria-label": string;
52	  "aria-required"?: true;
53	  "aria-invalid"?: true;
54	  "aria-describedby"?: string;
55	}
56	
57	/**
58	 * Everything `render` needs. Built ONCE per (row, column) by the shell —
59	 * see `StructuredListRow` below — and handed to `column.render`.
60	 */
61	export interface StructuredColumnContext<TRow extends object> {
62	  row: ProjectedRow<TRow>;
63	  /** Record an `update` edit for this row. Built via `useCallback` on
64	   *  `[onUpdateRow, row.rowId]`, but NOT stable across edits: the caller's
65	   *  `onUpdateRow` (normally `useStructuredRows`'s `updateRow`, whose deps
66	   *  include `rows`/`edits`) changes identity on every keystroke, so
67	   *  `update` does too. Never key a column's own `useCallback`/`useEffect`
68	   *  on it — that is the render-loop mechanic; call it only from plain
69	   *  event handlers. */
70	  update: (patch: Partial<TRow>) => void;
71	  /** Row-level disabled: the list's `disabled` OR `rowDisabled(row)`. */
72	  disabled: boolean;
73	  /** The row is soft-deleted — mirrors `row.softDeleted`, hoisted for
74	   *  convenience because most columns freeze on it. */
75	  removed: boolean;
76	  /** Accessible name every control in this cell MUST carry (`aria-label`),
77	   *  because the visible caption is `lg:hidden` and ARIA does not name a
78	   *  cell from its column header. Equals `column.header` unless the column
79	   *  overrides it with `ariaLabel`. */
80	  ariaLabel: string;
81	  /** `id` for a labelable control (`<input>`/`<textarea>`); the shell's
82	   *  caption uses no `htmlFor`, so this is only needed when the column
83	   *  wants a stable DOM id. */
84	  fieldId: string;
85	  /** `aria-describedby` target — the id of this cell's error element, or
86	   *  `undefined` when the cell has no error. */
87	  describedBy: string | undefined;
88	  /** At least one error binds to this cell. Drives the invalid ring so no
89	   *  type re-implements `useFieldError().hasError`. */
90	  invalid: boolean;
91	  /** The errors bound to this cell, already filtered by question + row +
92	   *  `errorFieldKeys`. Only read by columns that set `ownsErrorDisplay`. */
93	  errors: readonly QuestionValidationError[];
94	  /** `{ id: fieldId, "aria-label": ariaLabel, "aria-required"?,
95	   *  "aria-invalid"?, "aria-describedby"? }` — exactly the four fields
96	   *  above, bundled. Spread this directly onto the cell's control
97	   *  (`<Input {...ctx.controlProps} .../>`, `<RowStatusSelect
98	   *  {...ctx.controlProps} .../>`) instead of copying `ariaLabel`/`fieldId`/
99	   *  `describedBy`/`invalid` out one at a time — see
100	   *  {@link StructuredControlProps}'s doc comment for why this exists and
101	   *  what it does and does not guarantee. */
102	  controlProps: StructuredControlProps;
103	}
104	
105	/** ONE definition per field. Drives the desktop `columnheader` + `cell`
106	 *  AND the mobile caption + stacked field. There is no second definition.
107	 *
108	 *  Restricted to the prop surface current consumers genuinely need —
109	 *  `group`/`placement` (advanced fields, full-span notes rows) are
110	 *  deliberately absent; do not add them here without a real consumer. */
111	export interface StructuredColumn<TRow extends object> {
112	  /** Stable id. Used for the DOM anchor (`data-column`), the default
113	   *  `errorFieldKeys` entry, and React keys. */
114	  key: string;
115	  /** Already-translated header, e.g. `t("severity")`. Also the mobile
116	   *  caption and the default accessible name of every control in the cell. */
117	  header: string;
118	  /** Renders the `*` marker in the header and the mobile caption
119	   *  (`aria-hidden`; the programmatic signal is `aria-required` on the
120	   *  control). */
121	  required?: boolean;
122	  /** Desktop grid track. Ignored below `lg`. */
123	  width: string;
124	  /** Suppresses the desktop header text and the mobile caption. Use for an
125	   *  identity column whose value is already the row title
126	   *  (`rowTitle`/`rowSummary`). The column still renders and still
127	   *  occupies a track — only the label text is omitted. */
128	  headerHidden?: boolean;
129	  /** Column cell is not rendered at all below `lg` (its value already
130	   *  appears in `rowTitle`/`rowSummary`). Still occupies a desktop track. */
131	  mobileHidden?: boolean;
132	  /** Overrides the control's accessible name when the header is not a good
133	   *  one. */
134	  ariaLabel?: string;
135	  /** `field_key`s whose errors bind to this cell. Defaults to `[key]`. */
136	  errorFieldKeys?: readonly string[];
137	  /** The column renders its own `<StructuredFieldError>`. The shell then
138	   *  renders none for this cell but still computes `invalid`/`describedBy`. */
139	  ownsErrorDisplay?: boolean;
140	  /** Extra classes on the cell wrapper. */
141	  className?: string;
142	  render: (context: StructuredColumnContext<TRow>) => ReactNode;
143	}
144	
145	/**
146	 * One entry of a row's overflow menu, alongside the shell's own synthesized
147	 * Remove item. Remove itself is never listed here — it is always
148	 * shell-owned (`canRemoveRow`/`removeLabel` below), so a type cannot
149	 * accidentally duplicate or shadow it.
150	 *
151	 * Kept independent of `TRow` on purpose — unlike `StructuredColumn.render`,
152	 * an action has no per-cell context to receive (no `update`, no
153	 * `controlProps`); the `rowActions` callback below DOES receive the row and
154	 * hands back plain, already-bound callbacks here.
155	 */
156	export interface StructuredRowAction {
157	  /** Stable id — React key only, never rendered. */
158	  key: string;
159	  /** Already-translated label, e.g. `t("add_to_template")`. */
160	  label: ReactNode;
161	  icon?: ComponentType<{ className?: string }>;
162	  onSelect: () => void;
163	  disabled?: boolean;
164	  /** Red text, matching the shell's own Remove styling — for an action
165	   *  that is itself destructive/irreversible (not merely "not Remove"). */
166	  destructive?: boolean;
167	}
168	
169	export interface StructuredListProps<TRow extends object> {
170	  /** The owning question — namespaces every generated DOM id and scopes
171	   *  error matching. */
172	  questionId: string;
173	  /** Already-translated section label. Becomes the grid's `aria-label`. */
174	  label: string;
175	  rows: readonly ProjectedRow<TRow>[];
176	  columns: readonly StructuredColumn<TRow>[];
177	  errors: readonly QuestionValidationError[];
178	  /** Whole-section disabled (readonly mode, submit freeze). */
179	  disabled: boolean;
180	
181	  onUpdateRow: (rowId: RowId, patch: Partial<TRow>) => void;
182	  onRemoveRow: (rowId: RowId) => void;
183	
184	  /** The row's display name — desktop mobile-card title. */
185	  rowTitle: (row: ProjectedRow<TRow>) => ReactNode;
186	  /** One-line summary shown on a COLLAPSED mobile card. */
187	  rowSummary?: (row: ProjectedRow<TRow>) => ReactNode;
188	  /** Per-row disable beyond the section-level flag. Freezes the ENTIRE
189	   *  row, including the actions cell (`pointer-events-none` on the row
190	   *  div) — there is no way to distinguish "freeze the fields" from
191	   *  "freeze the fields but still let the clinician act on the row," so a
192	   *  type wanting a restore affordance on a disabled row cannot reach it
193	   *  through this prop as written. */
194	  rowDisabled?: (row: ProjectedRow<TRow>) => boolean;
195	  /** Domain state classes — e.g. `line-through` when resolved. */
196	  rowClassName?: (row: ProjectedRow<TRow>) => string | undefined;
197	  /** Already-translated remove label. Defaults to `t("remove")`. */
198	  removeLabel?: (row: ProjectedRow<TRow>) => string;
199	  /** `false` disables the remove affordance. Defaults to
200	   *  `(row) => !row.softDeleted`. */
201	  canRemoveRow?: (row: ProjectedRow<TRow>) => boolean;
202	  /** Extra per-row overflow-menu items, ABOVE the shell's own Remove item
203	   *  (a `DropdownMenuSeparator` is inserted between the two groups
204	   *  automatically, only when both are non-empty). Generic on purpose —
205	   *  any type may contribute actions here (e.g. `medication_request`/
206	   *  `service_request`'s per-row "Add to template"); see
207	   *  {@link StructuredRowAction}'s own doc comment. `undefined`/`[]`
208	   *  renders exactly the Remove-only menu. */
209	  rowActions?: (row: ProjectedRow<TRow>) => readonly StructuredRowAction[];
210	
211	  /** Rendered below the grid — the add-entity control. Kept a slot so the
212	   *  list never depends on the add flow. */
213	  addControl?: ReactNode;
214	}
215	
216	/**
217	 * ONE column/field definition per structured type, rendered as BOTH a
218	 * desktop grid row and a mobile collapsible card from the SAME React tree.
219	 *
220	 * The one breakpoint rule: layout differences are CSS, behaviour
221	 * differences are JavaScript. This component contains **zero**
222	 * `useBreakpoints` calls — `lg:`-prefixed Tailwind classes are the only
223	 * thing that ever switches a cell between "stacked card field" and "grid
224	 * row cell."
225	 *
226	 * `lg:grid-cols-[var(--structured-cols)]` MUST appear as a literal class
227	 * string (both here and in `StructuredListRow` below) so Tailwind v4's
228	 * scanner emits it — never templated.
229	 */
230	export function StructuredList<TRow extends object>({
231	  questionId,
232	  label,
233	  rows,
234	  columns,
235	  errors,
236	  disabled,
237	  onUpdateRow,
238	  onRemoveRow,
239	  rowTitle,
240	  rowSummary,
241	  rowDisabled,
242	  rowClassName,
243	  removeLabel,
244	  canRemoveRow,
245	  rowActions,
246	  addControl,
247	}: StructuredListProps<TRow>) {
248	  // Every column always occupies a track — actions is a fixed 48px track,
249	  // always last, always present: this is the row-actions MENU's track, not
250	  // a per-action column, so an arbitrary number of `rowActions` entries
251	  // never grows `--structured-cols` or requires a second header cell.
252	  const trackList = useMemo(
253	    () => gridTemplateColumns(columns, { actions: true }),
254	    [columns],
255	  );
256	
257	  return (
258	    <div data-structured-list={questionId} className="space-y-2">
259	      {rows.length > 0 && (
260	        // The ONLY horizontal scroller. Fixed px tracks must never reach an
261	        // element that participates in the canvas width.
262	        <div className="w-auto overflow-x-auto">
263	          <div className="min-w-fit lg:rounded-md lg:border lg:border-gray-200">
264	            <div
265	              role="table"
266	              aria-label={label}
267	              data-structured-grid
268	              style={{ "--structured-cols": trackList } as React.CSSProperties}
269	            >
270	              <div role="rowgroup" className="hidden lg:block">
271	                <div
272	                  role="row"
273	                  className="grid border-b border-gray-200 bg-gray-50 lg:grid-cols-[var(--structured-cols)]"
274	                >
275	                  {/* This loop's cell count (columns.length + 1 spacer)
276	                      MUST always match every body row's (columns.length +
277	                      1 actions, below) — header and body share one
278	                      `--structured-cols` track list, so a skipped cell
279	                      misaligns the desktop grid. Never conditionally OMIT
280	                      a header/body cell for a column; suppress its CONTENT
281	                      only (`headerHidden`/`mobileHidden` hide via CSS,
282	                      never by skipping the `.map()` entry). */}
283	                  {columns.map((column) => (
284	                    <div
285	                      key={column.key}
286	                      id={`${questionId}--${column.key}--header`}
287	                      role="columnheader"
288	                      className="border-r border-gray-200 p-3 text-sm font-semibold text-gray-600"
289	                    >
290	                      {!column.headerHidden && (
291	                        <>
292	                          {column.header}
293	                          {column.required && (
294	                            <span
295	                              aria-hidden="true"
296	                              className="ml-0.5 text-red-500"
297	                            >
298	                              *
299	                            </span>
300	                          )}
301	                        </>
302	                      )}
303	                    </div>
304	                  ))}
305	                  {/* role="none": layout-only spacer over the actions
306	                      track, never a phantom columnheader. */}
307	                  <div role="none" className="w-12" />
308	                </div>
309	              </div>
310	              <div role="rowgroup" className="bg-white">
311	                {rows.map((row, rowIndex) => (
312	                  <StructuredListRow
313	                    key={row.rowId}
314	                    questionId={questionId}
315	                    row={row}
316	                    rowIndex={rowIndex}
317	                    columns={columns}
318	                    errors={errors}
319	                    listDisabled={disabled}
320	                    onUpdateRow={onUpdateRow}
321	                    onRemoveRow={onRemoveRow}
322	                    rowTitle={rowTitle}
323	                    rowSummary={rowSummary}
324	                    rowDisabled={rowDisabled}
325	                    rowClassName={rowClassName}
326	                    removeLabel={removeLabel}
327	                    canRemoveRow={canRemoveRow}
328	                    rowActions={rowActions}
329	                  />
330	                ))}
331	              </div>
332	            </div>
333	          </div>
334	        </div>
335	      )}
336	      {addControl}
337	    </div>
338	  );
339	}
340	
341	interface StructuredListRowProps<TRow extends object> {
342	  questionId: string;
343	  row: ProjectedRow<TRow>;
344	  rowIndex: number;
345	  columns: readonly StructuredColumn<TRow>[];
346	  errors: readonly QuestionValidationError[];
347	  listDisabled: boolean;
348	  onUpdateRow: (rowId: RowId, patch: Partial<TRow>) => void;
349	  onRemoveRow: (rowId: RowId) => void;
350	  rowTitle: (row: ProjectedRow<TRow>) => ReactNode;
351	  rowSummary?: (row: ProjectedRow<TRow>) => ReactNode;
352	  rowDisabled?: (row: ProjectedRow<TRow>) => boolean;
353	  rowClassName?: (row: ProjectedRow<TRow>) => string | undefined;
354	  removeLabel?: (row: ProjectedRow<TRow>) => string;
355	  canRemoveRow?: (row: ProjectedRow<TRow>) => boolean;
356	  rowActions?: (row: ProjectedRow<TRow>) => readonly StructuredRowAction[];
357	}
358	
359	/**
360	 * One row, as its own component — NOT inlined into a `.map()` closure in
361	 * `StructuredList` — so `update`/`handleRemove` can be genuine per-row
362	 * `useCallback`s (stable while `onUpdateRow`/`onRemoveRow`/`row.rowId` are
363	 * unchanged) instead of fresh arrows built every render inside a loop,
364	 * which feeds unstable identities into children's hook dependencies.
365	 * Mobile expand/collapse is local, per-row state; every row starts
366	 * collapsed EXCEPT when it carries a bound error (below).
367	 */
368	function StructuredListRow<TRow extends object>({
369	  questionId,
370	  row,
371	  rowIndex,
372	  columns,
373	  errors,
374	  listDisabled,
375	  onUpdateRow,
376	  onRemoveRow,
377	  rowTitle,
378	  rowSummary,
379	  rowDisabled,
380	  rowClassName,
381	  removeLabel,
382	  canRemoveRow,
383	  rowActions,
384	}: StructuredListRowProps<TRow>) {
385	  const { t } = useTranslation();
386	  const [expanded, setExpanded] = useState(false);
387	  const toggleExpanded = useCallback(() => setExpanded((value) => !value), []);
388	
389	  const update = useCallback(
390	    (patch: Partial<TRow>) => onUpdateRow(row.rowId, patch),
391	    [onUpdateRow, row.rowId],
392	  );
393	  const handleRemove = useCallback(
394	    () => onRemoveRow(row.rowId),
395	    [onRemoveRow, row.rowId],
396	  );
397	
398	  const isDisabled = listDisabled || (rowDisabled?.(row) ?? false);
399	  const canRemove = canRemoveRow?.(row) ?? !row.softDeleted;
400	  const removeText = removeLabel?.(row) ?? t("remove");
401	  // Built fresh every render (not memoized) — deliberately: a type's
402	  // `rowActions` closure typically closes over its own per-row state (e.g.
403	  // `openAddToTemplate(row.row)`), and this shell has no way to know that
404	  // closure's real dependencies. Cheap: a handful of plain objects, not a
405	  // hook, so there is no rules-of-hooks concern with it running
406	  // conditionally-shaped output on every render.
407	  const extraActions = rowActions?.(row) ?? [];
408	  const bodyId = `${questionId}--${row.rowId}--body`;
409	
410	  // One scan for every error-driven decision this row makes — the forced
411	  // expansion, the unmatched-key fallback, and the mobile re-print of a
412	  // `mobileHidden` cell's error (all three rendered below).
413	  const { hasError, unmatchedFieldKeys, mobileHiddenErrorColumns } = useMemo(
414	    () =>
415	      resolveRowErrorState(columns, errors, {
416	        questionId,
417	        rowId: row.rowId,
418	        rowIndex,
419	      }),
420	    [columns, errors, questionId, row.rowId, rowIndex],
421	  );
422	
423	  // Below `lg` the body wrapper — the ONLY place a cell's
424	  // `StructuredFieldError` renders — is `display:none` while collapsed. A
425	  // row a blocking `validate()` error binds to must never be hideable that
426	  // way: `useSubmitFillSession` aborts the whole submit on any
427	  // `QuestionValidationError`, so a collapsed row would leave only a bare
428	  // toast and the error's `role="alert"` would never be announced from a
429	  // hidden subtree. `hasError` wins over the clinician's own toggle, which
430	  // regains control the instant the error clears.
431	  const isExpanded = expanded || hasError;
432	
433	  // DEV-ONLY accessible-name audit — the enforcement
434	  // `StructuredControlProps` itself cannot provide (see its doc comment).
435	  // Audits the ACTUAL RENDERED DOM — true regardless of which mechanism,
436	  // or none, a column's `render` used. `[data-column="<key>"]` is markup
437	  // every cell already carries, so this adds no new DOM. Runs once per
438	  // render (no dependency array — a broken cell should log on every render
439	  // until it's fixed), body-scoped so it only inspects THIS row's cells,
440	  // and a complete no-op outside development builds.
441	  const bodyRef = useRef<HTMLDivElement>(null);
442	  useEffect(() => {
443	    if (!import.meta.env.DEV) return;
444	    const body = bodyRef.current;
445	    if (!body) return;
446	    for (const column of columns) {
447	      auditCellAccessibleName(body, {
448	        questionId,
449	        rowId: row.rowId,
450	        columnKey: column.key,
451	      });
452	    }
453	  });
454	
455	  return (
456	    <div
457	      role="row"
458	      data-structured-row={row.rowId}
459	      className={cn(
460	        "grid grid-cols-1 border-b border-gray-200 last:border-b-0 lg:grid-cols-[var(--structured-cols)] lg:hover:bg-gray-50/50",
461	        isDisabled && "pointer-events-none opacity-40",
462	        rowClassName?.(row),
463	      )}
464	    >
465	      {/* Mobile card chrome. role="none" keeps it OUT of the cell index,
466	          so getByRole("cell").nth(n) maps to the declared column order. */}
467	      <div role="none" className="lg:hidden">
468	        <button
469	          type="button"
470	          aria-expanded={isExpanded}
471	          aria-controls={bodyId}
472	          onClick={toggleExpanded}
473	          // While `hasError` pins the row open there is no collapse action
474	          // to perform — disabling the toggle is the honest signal, instead
475	          // of a live control that visibly does nothing with
476	          // `aria-expanded` stuck at "true".
477	          disabled={hasError}
478	          className="flex w-full items-center justify-between gap-2 rounded-lg bg-gray-50 p-2 text-left active:bg-gray-100 disabled:cursor-not-allowed disabled:opacity-70"
479	        >
480	          <span className="min-w-0 break-words text-base text-gray-950">
481	            {rowTitle(row)}
482	          </span>
483	          {isExpanded ? (
484	            <ChevronsDownUp className="size-5 shrink-0" />
485	          ) : (
486	            <ChevronsUpDown className="size-5 shrink-0" />
487	          )}
488	        </button>
489	        {!isExpanded && rowSummary && (
490	          <p className="mt-1 px-2 text-sm text-gray-600">{rowSummary(row)}</p>
491	        )}
492	      </div>
493	
494	      <div
495	        id={bodyId}
496	        ref={bodyRef}
497	        role="none"
498	        className={cn(
499	          "space-y-3 p-2 lg:contents",
500	          !isExpanded && "hidden lg:contents",
501	        )}
502	      >
503	        {columns.map((column) => {
504	          const fieldKeys = column.errorFieldKeys ?? [column.key];
505	          const cellErrors = selectStructuredFieldErrors(errors, {
506	            questionId,
507	            rowId: row.rowId,
508	            rowIndex,
509	            fieldKeys,
510	          });
511	          const errorId = `${questionId}--${row.rowId}--${column.key}--error`;
512	          const ariaLabel = column.ariaLabel ?? column.header;
513	          const fieldId = `${questionId}--${row.rowId}--${column.key}`;
514	          const describedBy = cellErrors.length > 0 ? errorId : undefined;
515	          const invalid = cellErrors.length > 0;
516	          const context: StructuredColumnContext<TRow> = {
517	            row,
518	            update,
519	            disabled: isDisabled,
520	            removed: row.softDeleted,
521	            ariaLabel,
522	            fieldId,
523	            describedBy,
524	            invalid,
525	            errors: cellErrors,
526	            controlProps: {
527	              id: fieldId,
528	              "aria-label": ariaLabel,
529	              ...(column.required ? { "aria-required": true as const } : {}),
530	              ...(invalid ? { "aria-invalid": true as const } : {}),
531	              ...(describedBy ? { "aria-describedby": describedBy } : {}),
532	            },
533	          };
534	          return (
535	            <div
536	              key={column.key}
537	              role="cell"
538	              data-column={column.key}
539	              className={cn(
540	                "min-w-0 overflow-hidden px-1 py-1 lg:border-r lg:border-gray-200 lg:px-2 lg:py-1",
541	                column.mobileHidden && "hidden lg:block",
542	                column.className,
543	              )}
544	            >
545	              {!column.headerHidden && (
546	                <span
547	                  aria-hidden="true"
548	                  className="mb-1.5 block text-sm lg:hidden"
549	                >
550	                  {column.header}
551	                  {column.required && (
552	                    <span className="ml-0.5 text-red-500">*</span>
553	                  )}
554	                </span>
555	              )}
556	              {column.render(context)}
557	              {!column.ownsErrorDisplay && (
558	                <StructuredFieldError
559	                  id={errorId}
560	                  questionId={questionId}
561	                  rowId={row.rowId}
562	                  rowIndex={rowIndex}
563	                  fieldKeys={fieldKeys}
564	                  errors={errors}
565	                />
566	              )}
567	            </div>
568	          );
569	        })}
570	
571	        {/* Actions cell — never desktop-only: Remove must stay reachable
572	            at every width. Below `lg` a normal full-width flex row
573	            (reachable once the card is expanded, same as every other
574	            field); at `lg`+ the sticky right-aligned 48px track. */}
575	        <div
576	          role="cell"
577	          className={cn(
578	            "flex items-center justify-end gap-2 px-2 py-2",
579	            "lg:sticky lg:right-0 lg:w-12 lg:justify-center lg:bg-white lg:py-1 lg:shadow-[-12px_0_15px_-4px_rgba(0,0,0,0.15)]",
580	          )}
581	        >
582	          <DropdownMenu>
583	            <DropdownMenuTrigger asChild>
584	              <Button
585	                variant="ghost"
586	                size="icon"
587	                aria-label={t("row_actions")}
588	                disabled={isDisabled}
589	              >
590	                <MoreVertical className="h-4 w-4" />
591	              </Button>
592	            </DropdownMenuTrigger>
593	            <DropdownMenuContent align="end">
594	              {extraActions.map((action) => {
595	                const Icon = action.icon;
596	                return (
597	                  <DropdownMenuItem
598	                    key={action.key}
599	                    onSelect={action.onSelect}
600	                    disabled={action.disabled}
601	                    className={cn(action.destructive && "text-red-600")}
602	                  >
603	                    {Icon && <Icon className="mr-2 h-4 w-4" />}
604	                    <span>{action.label}</span>
605	                  </DropdownMenuItem>
606	                );
607	              })}
608	              {extraActions.length > 0 && canRemove && (
609	                <DropdownMenuSeparator />
610	              )}
611	              {canRemove && (
612	                <DropdownMenuItem
613	                  onSelect={handleRemove}
614	                  className="text-red-600"
615	                >
616	                  <Trash2 className="mr-2 h-4 w-4" />
617	                  <span>{removeText}</span>
618	                </DropdownMenuItem>
619	              )}
620	            </DropdownMenuContent>
621	          </DropdownMenu>
622	        </div>
623	
624	        {/* Below-`lg` re-print of a `mobileHidden` cell's error. That cell
625	            is `display:none` here, so its message — the shell's or the
626	            column's own — is unreachable at this width while the error
627	            still pins the row open, disables its collapse toggle and
628	            blocks Save. `lg:hidden` because at `lg`+ the cell itself is
629	            back and showing the same message; the id differs from the
630	            cell's (`--mobile-error`) so the two copies never collide. The
631	            caption names the field, which is otherwise only knowable from
632	            the desktop column header. */}
633	        {mobileHiddenErrorColumns.length > 0 && (
634	          <div role="none" className="space-y-1 px-1 pb-2 lg:hidden">
635	            {mobileHiddenErrorColumns.map((column) => (
636	              <div key={column.key}>
637	                {!column.headerHidden && (
638	                  <span aria-hidden="true" className="block text-sm">
639	                    {column.header}
640	                  </span>
641	                )}
642	                <StructuredFieldError
643	                  id={`${questionId}--${row.rowId}--${column.key}--mobile-error`}
644	                  questionId={questionId}
645	                  rowId={row.rowId}
646	                  rowIndex={rowIndex}
647	                  fieldKeys={column.errorFieldKeys ?? [column.key]}
648	                  errors={errors}
649	                />
650	              </div>
651	            ))}
652	          </div>
653	        )}
654	
655	        {/* Unmatched-error fallback. role="none" — like the mobile chrome
656	            above, this must never inject a phantom `role="cell"`, and
657	            `lg:col-span-full` spans every desktop track instead of
658	            claiming one (it isn't a column, so it never entered
659	            `gridTemplateColumns`'s count). One `StructuredFieldError` per
660	            distinct unmatched key — unlike a cell's "first error wins"
661	            slot, two undeclared keys can coexist and neither may be lost
662	            silently. */}
663	        {unmatchedFieldKeys.length > 0 && (
664	          <div
665	            role="none"
666	            className="space-y-1 px-1 pb-2 lg:col-span-full lg:px-2"
667	          >
668	            {unmatchedFieldKeys.map((fieldKey) => (
669	              <StructuredFieldError
670	                key={fieldKey}
671	                id={`${questionId}--${row.rowId}--${fieldKey}--error`}
672	                questionId={questionId}
673	                rowId={row.rowId}
674	                rowIndex={rowIndex}
675	                fieldKeys={[fieldKey]}
676	                errors={errors}
677	              />
678	            ))}
679	          </div>
680	        )}
681	      </div>
682	    </div>
683	  );
684	}
685	
686	/** Interactive elements a cell's control could plausibly be — anything a
687	 *  screen reader would announce as a distinct, actionable widget. A cell
688	 *  with none of these (a pure display value, e.g. `charge_item`'s "item"
689	 *  column) has nothing to name and is silently skipped below. */
690	const INTERACTIVE_SELECTOR =
691	  'input, textarea, select, button, [role="combobox"], [role="button"], [contenteditable="true"]';
692	
693	/**
694	 * DEV-ONLY. Warns loudly, via `console.error`, when a structured cell's
695	 * control has no accessible name — the enforcement `StructuredControlProps`
696	 * itself cannot provide (see that interface's doc comment). Checked against
697	 * the real, committed DOM rather than against however the column's `render`
698	 * happened to wire its props, so this catches every failure mode: a
699	 * forgotten `aria-label`, one spread onto a custom component that doesn't
700	 * declare it, a `<label>` with no matching `id`, all the same to a screen
701	 * reader and all the same here.
702	 *
703	 * A cell with no interactive control at all (a pure display column) is not
704	 * an error and is not reported — there is nothing in it to name.
705	 */
706	function auditCellAccessibleName(
707	  body: HTMLElement,
708	  context: { questionId: string; rowId: RowId; columnKey: string },
709	): void {
710	  const cell = body.querySelector<HTMLElement>(
711	    `[data-column="${context.columnKey}"]`,
712	  );
713	  if (!cell) return;
714	  const control = cell.querySelector<HTMLElement>(INTERACTIVE_SELECTOR);
715	  if (!control) return; // pure-display column — nothing to name
716	
717	  const hasLabelFor =
718	    !!control.id &&
719	    !!control.ownerDocument.querySelector(`label[for="${control.id}"]`);
720	  const named =
721	    !!control.getAttribute("aria-label")?.trim() ||
722	    !!control.getAttribute("aria-labelledby") ||
723	    hasLabelFor;
724	
725	  if (!named) {
726	    console.error(
727	      `StructuredList: column "${context.columnKey}" in question "${context.questionId}" (row ${context.rowId}) rendered a control with no accessible name. Spread ctx.controlProps (or set aria-label from ctx.ariaLabel) onto it — the visible caption is lg:hidden, so this is the only name a screen reader gets.`,
728	    );
729	  }
730	}
