2	import { describe, it } from "node:test";
3	
4	import type { QuestionValidationError } from "@/types/questionnaire/batch";
5	
6	import { selectStructuredFieldErrors } from "./structuredFieldErrors";
7	
8	const err = (
9	  over: Partial<QuestionValidationError> = {},
10	): QuestionValidationError => ({
11	  question_id: "q-1",
12	  field_key: "slot_id",
13	  error: "error",
14	  ...over,
15	});
16	
17	describe("selectStructuredFieldErrors", () => {
18	  it("binds on question_id + field_key + row_id", () => {
19	    const error = err({ row_id: "row-1" });
20	    assert.deepEqual(
21	      selectStructuredFieldErrors([error], {
22	        questionId: "q-1",
23	        rowId: "row-1",
24	        fieldKeys: ["slot_id"],
25	      }),
26	      [error],
27	    );
28	  });
29	
30	  it("does NOT bind across question ids (two questions of the same type)", () => {
31	    const error = err({ question_id: "q-2", row_id: "row-1" });
32	    assert.deepEqual(
33	      selectStructuredFieldErrors([error], {
34	        questionId: "q-1",
35	        rowId: "row-1",
36	        fieldKeys: ["slot_id"],
37	      }),
38	      [],
39	    );
40	  });
41	
42	  it("does NOT bind across field_keys", () => {
43	    const error = err({ field_key: "note", row_id: "row-1" });
44	    assert.deepEqual(
45	      selectStructuredFieldErrors([error], {
46	        questionId: "q-1",
47	        rowId: "row-1",
48	        fieldKeys: ["slot_id"],
49	      }),
50	      [],
51	    );
52	  });
53	
54	  it("does NOT bind across row_ids", () => {
55	    const error = err({ row_id: "row-1" });
56	    assert.deepEqual(
57	      selectStructuredFieldErrors([error], {
58	        questionId: "q-1",
59	        rowId: "row-2",
60	        fieldKeys: ["slot_id"],
61	      }),
62	      [],
63	    );
64	  });
65	
66	  it("v1 fallback: an error with `index` and no `row_id` binds by rowIndex", () => {
67	    const error = err({ index: 2 });
68	    assert.deepEqual(
69	      selectStructuredFieldErrors([error], {
70	        questionId: "q-1",
71	        rowIndex: 2,
72	        fieldKeys: ["slot_id"],
73	      }),
74	      [error],
75	    );
76	  });
77	
78	  it("an error carrying BOTH row_id and index prefers row_id (row_id wins, and does NOT also match a different rowId that shares the index)", () => {
79	    const error = err({ row_id: "row-1", index: 2 });
80	    // Matching the carried row_id succeeds even though rowIndex differs.
81	    assert.deepEqual(
82	      selectStructuredFieldErrors([error], {
83	        questionId: "q-1",
84	        rowId: "row-1",
85	        rowIndex: 99,
86	        fieldKeys: ["slot_id"],
87	      }),
88	      [error],
89	    );
90	    // A DIFFERENT row that happens to share the index must NOT match —
91	    // row_id's presence on the error stops the index fallback entirely.
92	    assert.deepEqual(
93	      selectStructuredFieldErrors([error], {
94	        questionId: "q-1",
95	        rowId: "row-2",
96	        rowIndex: 2,
97	        fieldKeys: ["slot_id"],
98	      }),
99	      [],
100	    );
101	  });
102	
103	  it("an error with NEITHER binds only to a section-level slot (rowId === undefined && rowIndex === undefined)", () => {
104	    const error = err();
105	    assert.deepEqual(
106	      selectStructuredFieldErrors([error], {
107	        questionId: "q-1",
108	        fieldKeys: ["slot_id"],
109	      }),
110	      [error],
111	    );
112	  });
113	
114	  it("a section-level slot does NOT swallow a row-scoped error", () => {
115	    const error = err();
116	    assert.deepEqual(
117	      selectStructuredFieldErrors([error], {
118	        questionId: "q-1",
119	        rowId: "row-1",
120	        fieldKeys: ["slot_id"],
121	      }),
122	      [],
123	    );
124	  });
125	
126	  it("multiple field keys: a column owning sub-fields matches any of them", () => {
127	    const error = err({ field_key: "dose_quantity", row_id: "row-1" });
128	    assert.deepEqual(
129	      selectStructuredFieldErrors([error], {
130	        questionId: "q-1",
131	        rowId: "row-1",
132	        fieldKeys: ["dose_quantity", "dose_unit"],
133	      }),
134	      [error],
135	    );
136	  });
137	
138	  it("an empty-string field_key is treated the same as no field_key at all — never matches through this primitive, aligned with QuestionBlock.tsx's own falsy check", () => {
139	    const error = err({ field_key: "" });
140	    // Neither a section-level query (no rowId/rowIndex)...
141	    assert.deepEqual(
142	      selectStructuredFieldErrors([error], {
143	        questionId: "q-1",
144	        fieldKeys: ["slot_id"],
145	      }),
146	      [],
147	    );
148	    // ...nor a row-scoped one matches: `""` is not a real field key. This
149	    // is what keeps the error from vanishing entirely — QuestionBlock.tsx's
150	    // `!error.field_key` filter treats it identically (falsy), so it stays
151	    // in the BLOCK-level list precisely because this primitive never
152	    // claims it.
153	    assert.deepEqual(
154	      selectStructuredFieldErrors([error], {
155	        questionId: "q-1",
156	        rowId: "row-1",
157	        fieldKeys: ["slot_id"],
158	      }),
159	      [],
160	    );
161	  });
162	
163	  it("order is preserved (the first binding error is what renders)", () => {
