    );
  });

  it("an error bound to a DIFFERENT row does not list the column", () => {
    assert.deepEqual(
      resolveRowErrorState(
        [{ key: "quantity", mobileHidden: true }],
        [err({ row_id: "row-2" })],
        match,
      ).mobileHiddenErrorColumns,
      [],
    );
  });
});

